fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    assert!(a.len() == b.len(), "Input vectors must have the same length");
    a.iter()
     .zip(b.iter())
     .map(|(x, y)| x >= y)
     .collect()
}